package cl.nexbyte.siger.institucional.nucleo;

import cl.nexbyte.siger.institucional.robustez.*;
import cl.nexbyte.siger.institucional.identidad.*;
import cl.nexbyte.siger.institucional.nucleo.CatalogoLaboratorio.Operador;
import static cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;
import java.time.Clock;
import java.util.*;
import tools.jackson.databind.json.JsonMapper;

/** SOL, REQ y colaboración institucional. Comparte el cerrojo COM, identidad e idempotencia
 * del núcleo, pero nunca infiere nacimiento, principal o cierre a partir de Casos históricos. */
public final class NucleoU2 {
    public record Encaminar(long revision,NuevoDestino destino,String clasificacion,String domicilioRegion){@Override public String toString(){return "Encaminar[datos protegidos]";}}
    public record Asumir(long revision,String responsable,String fundamento,String fundamentoTerritorial){@Override public String toString(){return "Asumir[datos protegidos]";}}
    public record PrimeraAtencion(Manual comunicacion,NuevoDestino ambito,String respuesta){@Override public String toString(){return "PrimeraAtencion[datos protegidos]";}}
    public record AsumirPropia(long revision,NuevoDestino destino,String responsable,String fundamento,String fundamentoTerritorial){@Override public String toString(){return "AsumirPropia[datos protegidos]";}}
    public record Apertura(long revision,String responsable,String objetivo){@Override public String toString(){return "Apertura[datos protegidos]";}}
    public record Colaborar(long revision,NuevoDestino destino,String objetivo){@Override public String toString(){return "Colaborar[datos protegidos]";}}
    public record ResolverColaboracion(long revision,String decision,String responsable,String fundamento){@Override public String toString(){return "ResolverColaboracion[datos protegidos]";}}
    private final BaseJdbc db;private final NucleoInstitucional core;private final CatalogoLaboratorio cat;private final Clock clock;private final JsonMapper json;private final PoliticaAreas areas;
    NucleoU2(BaseJdbc db,NucleoInstitucional core,CatalogoLaboratorio cat,Clock clock,JsonMapper json){this.db=db;this.core=core;this.cat=cat;this.clock=clock;this.json=json;areas=new PoliticaAreas(db,clock);}
    private static String id(UUID u){if(u==null)throw new FalloTecnico(400);return u.toString();}
    private static UUID uuid(Object o){return UUID.fromString(o.toString());}
    private static long n(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();}
    private static String s(Map<String,Object> r,String k){return r.get(k)==null?null:r.get(k).toString();}
    private static void texto(String t,int max){try{cl.nexbyte.siger.contrato.DeclaracionNna.texto(t==null?null:t.replace("\r"," ").replace("\n"," ").replace("\t"," "),max,true);}catch(IllegalArgumentException e){throw new FalloTecnico(400);}}
    private static Map<String,Object> normal(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();row.forEach((k,v)->out.put(k.toLowerCase(Locale.ROOT),v));return out;}
    private List<Map<String,Object>> normalList(String sql,Object... args){return db.sql.queryForList(sql,args).stream().map(NucleoU2::normal).toList();}
    private static UUID sub(UUID key,String action){return UUID.nameUUIDFromBytes((key+":"+action).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    private void guard(Operador a){core.bloquearAcceso(a);if(!cat.individual())throw new FalloTecnico(409,"IDENTIDAD_INDIVIDUAL_REQUERIDA");}
    private static void version(Map<String,Object> r,long v){if(v<0||n(r,"revision")!=v)throw new FalloTecnico(409,"VERSION_OBSOLETA");}
    private Map<String,Object> uno(String sql,Object... args){var rows=db.sql.queryForList(sql,args);if(rows.isEmpty())throw new FalloTecnico(404);return rows.getFirst();}
    private Map<String,Object> sol(UUID id){return uno("SELECT s.*,d.unit_code,d.site_id,a.area_id FROM institution_sol s JOIN core_destination d ON d.id=s.destination_id LEFT JOIN destination_area a ON a.destination_id=d.id WHERE s.id=?",id(id));}
    private Map<String,Object> req(UUID id){return uno("SELECT q.*,i.* FROM core_requirement q JOIN institution_req i ON i.requirement_id=q.id WHERE q.id=?",id(id));}
    private void abierto(Map<String,Object> r){if(!"ACTIVO".equals(r.get("state")))throw new FalloTecnico(409,"REQ_CERRADO");}
    private void jefatura(Operador a,Map<String,Object> r){if(!vigente(r)||!a.jefeEn(s(r,"unit_code"),s(r,"site_id"),s(r,"area_id")))throw new FalloTecnico(404);}
    private boolean vigente(Map<String,Object> r){return r.get("area_id")==null||areas.vigente(s(r,"area_id"),s(r,"unit_code"),s(r,"site_id"));}
    private boolean encargado(Operador a,Map<String,Object> r){return a.id().equals(r.get("attention_actor"))&&habilitado(a,s(r,"unit_code"),s(r,"site_id"),s(r,"area_id"));}
    private boolean habilitado(Operador a,String u,String sede,String ar){return a.jefeEn(u,sede,ar)||a.profesionalEn(u,sede,ar)||a.accesos().stream().anyMatch(x->x.rol().equals("ADMINISTRATIVO")&&Objects.equals(x.area(),ar)&&x.cubre(u,sede,ar));}
    private void lector(Operador a,Map<String,Object> r){if(!vigente(r)||!(encargado(a,r)||a.jefeEn(s(r,"unit_code"),s(r,"site_id"),s(r,"area_id"))))throw new FalloTecnico(404);}
    private Operador responsable(String actor,NuevoDestino d){if(actor==null)throw new FalloTecnico(400);var a=cat.operador(actor);boolean valid=a.jefeEn(d.unidad(),d.sede(),d.area())||a.profesionalEn(d.unidad(),d.sede(),d.area());if(!valid)throw new FalloTecnico(400,"RESPONSABLE_FUERA_AREA");return a;}
    private void ambito(NuevoDestino d){if(d==null)throw new FalloTecnico(400);areas.exigirAreaParaAlta(d.area(),d.unidad(),d.sede());if(cat.presencias().stream().noneMatch(x->x.unidad().equals(d.unidad())&&x.sede().equals(d.sede())))throw new FalloTecnico(400);if(d.area()!=null)new CatalogoAreas(db,clock).exigir(d.area(),d.unidad(),d.sede());if(!cat.operador(d.evaluador()).jefeEn(d.unidad(),d.sede(),d.area()))throw new FalloTecnico(400,"JEFATURA_NO_VIGENTE");}
    private NuevoDestino destino(Map<String,Object> r,String jefe){return new NuevoDestino(s(r,"unit_code"),s(r,"site_id"),jefe,s(r,"area_id"));}
    private UUID crearDestino(UUID com,NuevoDestino d,Operador a){ambito(d);UUID id=UUID.randomUUID();db.sql.update("INSERT INTO core_destination(id,communication_id,unit_code,site_id,evaluator_id,state,revision,created_ms,created_by) VALUES(?,?,?,?,?,'EVALUANDO',0,?,?)",id(id),id(com),d.unidad(),d.sede(),d.evaluador(),clock.millis(),a.id());if(d.area()!=null)db.sql.update("INSERT INTO destination_area VALUES(?,?)",id(id),d.area());return id;}
    private void historia(UUID com,UUID recurso,String tipo,long revision,Operador a,String action,String reason,Object snapshot){db.sql.update("INSERT INTO institution_flow_history(communication_id,resource_id,resource_kind,revision,actor_id,at_ms,action_code,reason_text,snapshot_doc) VALUES(?,?,?,?,?,?,?,?,?)",id(com),id(recurso),tipo,revision,a.id(),clock.millis(),action,reason,json.writeValueAsString(snapshot));core.event(com,tipo,recurso,a,action);}
    private void bumpCom(UUID com){db.sql.update("UPDATE core_communication SET revision=revision+1 WHERE id=?",id(com));}
    private void sinHistoriaProvisional(UUID com){if(db.sql.queryForObject("SELECT COUNT(*) FROM core_destination WHERE communication_id=?",Long.class,id(com))>0||db.sql.queryForObject("SELECT COUNT(*) FROM core_requirement WHERE communication_id=?",Long.class,id(com))>0)throw new FalloTecnico(409,"HISTORICO_REQUIERE_CONCILIACION");}
    private boolean regional(String sede){if(sede==null)return false;if(db.sql.queryForObject("SELECT COUNT(*) FROM matter_regional_site WHERE site_id=?",Long.class,sede)>0){new CatalogoMaterias(db,clock).exigirSede(sede);return true;}return cat.operadores().stream().flatMap(o->o.accesos().stream()).anyMatch(x->x.rol().equals("COORDINADOR_REGIONAL")&&Objects.equals(x.sede(),sede));}
    private void distribuidor(Operador a,UUID com,NuevoDestino target){var source=db.sql.queryForList("SELECT site_id FROM communication_origin WHERE communication_id=? AND origin_code='REGISTRO_FUNCIONARIO'",id(com));String site=source.isEmpty()?null:s(source.getFirst(),"site_id");
        if(regional(site)){if(!Objects.equals(site,target.sede())||a.accesos().stream().noneMatch(x->x.rol().equals("COORDINADOR_REGIONAL")&&Objects.equals(x.sede(),site)))throw new FalloTecnico(403);}
        else if(!a.distribuidor())throw new FalloTecnico(403);
    }
    /** Primera distribución: una SOL, un destino. Clasificar nunca crea REQ. */
    public Resultado distribuir(Operador a,UUID key,UUID com,Encaminar r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"U2_DISTRIBUIR",List.of(com,r),()->{guard(a);var c=core.lock(com);if(r.destino()==null)throw new FalloTecnico(400);distribuidor(a,com,r.destino());version(c,r.revision());if(!"ABIERTA".equals(c.get("state")))throw new FalloTecnico(409);sinHistoriaProvisional(com);texto(r.clasificacion(),2000);if(r.domicilioRegion()!=null&&db.sql.queryForObject("SELECT COUNT(*) FROM org_region WHERE id=?",Long.class,r.domicilioRegion())!=1)throw new FalloTecnico(400);UUID d=crearDestino(com,r.destino(),a),sol=UUID.randomUUID();db.sql.update("INSERT INTO institution_sol VALUES(?,?,?,'PENDIENTE',0,?,?,?,?)",id(sol),id(com),id(d),r.clasificacion(),r.domicilioRegion(),a.id(),clock.millis());historia(com,sol,"SOL",0,a,"SOL_DISTRIBUIDA",r.clasificacion(),r);bumpCom(com);return new Resultado(sol,0);});}
    public Resultado redirigir(Operador a,UUID key,UUID sol,Encaminar r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"U2_REDIRIGIR",List.of(sol,r),()->{guard(a);var initial=sol(sol);UUID com=uuid(initial.get("communication_id"));core.lock(com);var row=sol(sol);jefatura(a,row);version(row,r.revision());if(!"PENDIENTE".equals(row.get("state")))throw new FalloTecnico(409);texto(r.clasificacion(),2000);ambito(r.destino());if(Objects.equals(row.get("unit_code"),r.destino().unidad())&&Objects.equals(row.get("site_id"),r.destino().sede())&&Objects.equals(row.get("area_id"),r.destino().area()))throw new FalloTecnico(409);if(!Objects.equals(row.get("domicile_region"),r.domicilioRegion()))throw new FalloTecnico(409,"DOMICILIO_DECLARADO_INMUTABLE");UUID d=crearDestino(com,r.destino(),a);db.sql.update("UPDATE core_destination SET state='RESUELTO',revision=revision+1,decision='REDIRECCION_SOL',decision_text=?,decided_by=?,decided_ms=? WHERE id=?",r.clasificacion(),a.id(),clock.millis(),row.get("destination_id"));db.sql.update("UPDATE institution_sol SET destination_id=?,revision=revision+1,classification_text=? WHERE id=?",id(d),r.clasificacion(),id(sol));historia(com,sol,"SOL",r.revision()+1,a,"SOL_REDIRIGIDA",r.clasificacion(),r);bumpCom(com);return new Resultado(sol,r.revision()+1);});}
    private long autoridad(){long rev=db.sql.queryForObject("SELECT revision FROM authority_registry WHERE id=1",Long.class);var batch=uno("SELECT expires_ms FROM authority_batch WHERE revision=?",rev);if(n(batch,"expires_ms")<=clock.millis())throw new FalloTecnico(403,"AUTORIDAD_NO_ACREDITADA");return rev;}
    /** Una jefatura competente puede asumir su propio ingreso, sin remitirlo artificialmente a central. */
    public Resultado asumirPropia(Operador a,UUID key,UUID com,AsumirPropia r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"U2_ASUMIR_INGRESO_PROPIO",List.of(com,r),()->{
        guard(a);var root=core.lock(com);version(root,r.revision());if(!"ABIERTA".equals(root.get("state")))throw new FalloTecnico(409);sinHistoriaProvisional(com);
        if(db.sql.queryForObject("SELECT COUNT(*) FROM core_manual WHERE communication_id=? AND actor_id=?",Long.class,id(com),a.id())!=1)throw new FalloTecnico(404);
        var d=r.destino();ambito(d);if(!a.jefeEn(d.unidad(),d.sede(),d.area()))throw new FalloTecnico(404);responsable(r.responsable(),d);texto(r.fundamento(),2000);if(regional(d.sede()))texto(r.fundamentoTerritorial(),2000);
        var dest=crearDestino(com,d,a);var sol=UUID.randomUUID();db.sql.update("INSERT INTO institution_sol VALUES(?,?,?,'ASUMIDA',1,?,NULL,?,?)",id(sol),id(com),id(dest),r.fundamento(),a.id(),clock.millis());var req=crearReq(com,sol,dest,d,r.responsable(),a,"ASUNCION_SOL");historia(com,sol,"SOL",1,a,"SOL_ASUMIDA_EN_INGRESO_PROPIO",r.fundamento(),r);historia(com,req,"REQ",0,a,"REQ_NACIDO_POR_ASUNCION",r.fundamento(),r);bumpCom(com);return new Resultado(req,0);
    });}
    private UUID crearReq(UUID com,UUID sol,UUID d,NuevoDestino context,String responsible,Operador a,String origin){UUID req=UUID.randomUUID();db.sql.update("INSERT INTO core_requirement(id,communication_id,state,revision,created_ms,created_by) VALUES(?,?,'ACTIVO',0,?,?)",id(req),id(com),clock.millis(),a.id());db.sql.update("INSERT INTO institution_req VALUES(?,?,?,?,?,?,?,NULL,?,?)",id(req),sol==null?null:id(sol),id(d),context.unidad(),context.sede(),context.area(),responsible,autoridad(),origin);return req;}
    public Resultado asumir(Operador a,UUID key,UUID sol,Asumir r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"U2_ASUMIR",List.of(sol,r),()->{guard(a);var row=sol(sol);UUID com=uuid(row.get("communication_id"));core.lock(com);row=sol(sol);jefatura(a,row);version(row,r.revision());if(!"PENDIENTE".equals(row.get("state")))throw new FalloTecnico(409);texto(r.fundamento(),2000);var d=destino(row,a.id());ambito(d);responsable(r.responsable(),d);
        // No se confunden domicilio, lugar de hechos ni sede capturadora. Sin cobertura institucional
        // acreditada, una recepción regional exige decisión territorial fundada de su propia jefatura.
        if(regional(d.sede())){if(row.get("domicile_region")!=null)throw new FalloTecnico(409,"COBERTURA_TERRITORIAL_NO_ACREDITADA");texto(r.fundamentoTerritorial(),2000);}
        UUID req=crearReq(com,sol,uuid(row.get("destination_id")),d,r.responsable(),a,"ASUNCION_SOL");db.sql.update("UPDATE institution_sol SET state='ASUMIDA',revision=revision+1 WHERE id=?",id(sol));historia(com,sol,"SOL",r.revision()+1,a,"SOL_ASUMIDA",r.fundamento(),r);historia(com,req,"REQ",0,a,"REQ_NACIDO_POR_ASUNCION",r.fundamento(),r);bumpCom(com);return new Resultado(req,0);});}
    /** La respuesta y el REQ finalizado son atómicos con el registro de la COM original. */
    public Resultado primeraAtencion(Operador a,UUID key,PrimeraAtencion r){if(r==null||r.comunicacion()==null||r.comunicacion().respuestaYaEntregada()!=null)throw new FalloTecnico(400);return core.execute(key,a,"U2_PRIMERA_ATENCION",r,()->{guard(a);var d=r.ambito();ambito(d);if(!habilitado(a,d.unidad(),d.sede(),d.area()))throw new FalloTecnico(403);texto(r.respuesta(),12000);var com=core.registrarManual(a,sub(key,"COM"),r.comunicacion()).id();core.lock(com);var dest=crearDestino(com,d,a);var req=crearReq(com,null,dest,d,a.id(),a,"PRIMERA_ATENCION");db.sql.update("UPDATE core_requirement SET state='TERMINADO',revision=1,ended_ms=? WHERE id=?",clock.millis(),id(req));db.sql.update("UPDATE core_destination SET state='RESUELTO' WHERE id=?",id(dest));historia(com,req,"REQ",1,a,"PRIMERA_ATENCION_RESUELTA",r.respuesta(),r.ambito());bumpCom(com);return new Resultado(req,1);});}
    public Resultado actuar(Operador a,UUID key,UUID req,Decision r,boolean cerrar){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,cerrar?"U2_CERRAR_REQ":"U2_ACTUAR_REQ",List.of(req,r),()->{guard(a);var row=req(req);UUID com=uuid(row.get("communication_id"));core.lock(com);row=req(req);lector(a,row);version(row,r.revision());abierto(row);texto(r.texto(),12000);long cases=db.sql.queryForObject("SELECT COUNT(*) FROM core_case WHERE requirement_id=?",Long.class,id(req));if(cases>0){if(!cerrar)throw new FalloTecnico(409,"ACTUACION_REQUIERE_CASO");jefatura(a,row);}if(cerrar&&(db.sql.queryForObject("SELECT COUNT(*) FROM core_case WHERE requirement_id=? AND state<>'CERRADO'",Long.class,id(req))>0||db.sql.queryForObject("SELECT COUNT(*) FROM institution_collaboration WHERE requirement_id=? AND state='PENDIENTE'",Long.class,id(req))>0))throw new FalloTecnico(409,"REQ_INTERVENCIONES_PENDIENTES");db.sql.update("UPDATE core_requirement SET revision=revision+1,state=?,ended_ms=? WHERE id=?",cerrar?"TERMINADO":"ACTIVO",cerrar?clock.millis():null,id(req));historia(com,req,"REQ",r.revision()+1,a,cerrar?"REQ_CIERRE_EXPLICITO":"REQ_ATENCION_SIN_CASO",r.texto(),Map.of("casos",cases));bumpCom(com);return new Resultado(req,r.revision()+1);});}
    public Resultado clasificar(Operador a,UUID key,UUID req,Clasificacion r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"U2_COMPLEJIDAD_REQ",List.of(req,r),()->{guard(a);var row=req(req);UUID com=uuid(row.get("communication_id"));core.lock(com);row=req(req);jefatura(a,row);version(row,r.revision());abierto(row);texto(r.fundamento(),2000);if(r.clasificacion()!=null&&!Set.of("BAJA","MEDIANA","ALTA").contains(r.clasificacion()))throw new FalloTecnico(400);db.sql.update("UPDATE institution_req SET complexity=? WHERE requirement_id=?",r.clasificacion(),id(req));db.sql.update("UPDATE core_requirement SET revision=revision+1 WHERE id=?",id(req));historia(com,req,"REQ",r.revision()+1,a,"REQ_COMPLEJIDAD",r.fundamento(),r);bumpCom(com);return new Resultado(req,r.revision()+1);});}
    private Resultado abrir(Operador a,UUID key,Map<String,Object> row,UUID d,String responsible,String objective){texto(objective,2000);var result=core.abrirCaso(a,sub(key,"CAS"),d,new Asignacion(db.sql.queryForObject("SELECT revision FROM core_destination WHERE id=?",Long.class,id(d)),responsible,null));db.sql.update("INSERT INTO institution_case VALUES(?,?)",id(result.id()),objective);historia(uuid(row.get("communication_id")),result.id(),"CASO",0,a,"CASO_OBJETIVO_INDEPENDIENTE",objective,Map.of("requerimiento",row.get("id")));return result;}
    public Resultado abrirCaso(Operador a,UUID key,UUID req,Apertura r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"U2_ABRIR_CASO",List.of(req,r),()->{guard(a);var row=req(req);core.lock(uuid(row.get("communication_id")));row=req(req);jefatura(a,row);version(row,r.revision());abierto(row);responsable(r.responsable(),destino(row,a.id()));var result=abrir(a,key,row,uuid(row.get("principal_destination")),r.responsable(),r.objetivo());db.sql.update("UPDATE core_requirement SET revision=revision+1 WHERE id=?",id(req));return result;});}
    public Resultado colaborar(Operador a,UUID key,UUID req,Colaborar r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"U2_COLABORACION",List.of(req,r),()->{guard(a);var row=req(req);UUID com=uuid(row.get("communication_id"));core.lock(com);row=req(req);jefatura(a,row);version(row,r.revision());abierto(row);ambito(r.destino());texto(r.objetivo(),2000);if(Objects.equals(row.get("unit_code"),r.destino().unidad())&&Objects.equals(row.get("site_id"),r.destino().sede())&&Objects.equals(row.get("area_id"),r.destino().area()))throw new FalloTecnico(409);UUID proposal=UUID.randomUUID();db.sql.update("INSERT INTO institution_collaboration VALUES(?,?,?,?,?,?,'PENDIENTE',0,?,?,NULL)",id(proposal),id(req),r.destino().unidad(),r.destino().sede(),r.destino().area(),r.objetivo(),a.id(),clock.millis());db.sql.update("UPDATE core_requirement SET revision=revision+1 WHERE id=?",id(req));historia(com,proposal,"COLABORACION",0,a,"COLABORACION_SOLICITADA",r.objetivo(),r.destino());bumpCom(com);return new Resultado(proposal,0);});}
    public Resultado resolver(Operador a,UUID key,UUID proposal,ResolverColaboracion r){if(r==null)throw new FalloTecnico(400);return core.execute(key,a,"U2_DECIDIR_COLABORACION",List.of(proposal,r),()->{guard(a);var p=uno("SELECT * FROM institution_collaboration WHERE id=?",id(proposal));var row=req(uuid(p.get("requirement_id")));UUID com=uuid(row.get("communication_id"));core.lock(com);row=req(uuid(p.get("requirement_id")));p=uno("SELECT * FROM institution_collaboration WHERE id=?",id(proposal));version(p,r.revision());if(!"PENDIENTE".equals(p.get("state")))throw new FalloTecnico(409);abierto(row);texto(r.fundamento(),2000);if("RETIRADA".equals(r.decision()))jefatura(a,row);else jefatura(a,p);UUID caso=null;if("ACEPTADA".equals(r.decision())){var d=destino(p,a.id());ambito(d);responsable(r.responsable(),d);UUID destination=crearDestino(com,d,a);caso=abrir(a,key,row,destination,r.responsable(),s(p,"objective_text")).id();}else if(!Set.of("RECHAZADA","RETIRADA").contains(r.decision()))throw new FalloTecnico(400);db.sql.update("UPDATE institution_collaboration SET state=?,revision=revision+1,case_id=? WHERE id=?",r.decision(),caso==null?null:id(caso),id(proposal));db.sql.update("UPDATE core_requirement SET revision=revision+1 WHERE id=?",row.get("id"));historia(com,proposal,"COLABORACION",r.revision()+1,a,"COLABORACION_"+r.decision(),r.fundamento(),Map.of("caso",caso==null?"":id(caso)));bumpCom(com);return new Resultado(proposal,r.revision()+1);});}
    private boolean gestionaCaso(Operador a,Map<String,Object> row){try{core.autorizarCaso(a,uuid(row.get("id")));return true;}catch(FalloTecnico e){if(e.status==404)return false;throw e;}}
    private static String lit(String v){if(v==null)return "NULL";if(!v.matches("[A-Za-z0-9_.-]{1,64}"))throw new FalloTecnico(403);return "'"+v+"'";}
    /** Búsqueda exacta de referencia para distribución: ni relato ni Casos del REQ mixto. */
    public List<Map<String,Object>> referencias(Operador a,String folio){return db.transaction(()->{guard(a);if(!a.distribuidor())throw new FalloTecnico(403);if(folio==null||!folio.matches("[A-Z0-9-]{3,40}"))throw new FalloTecnico(400);return normalList("SELECT q.id AS requirement_id,q.communication_id,q.state,i.unit_code,i.site_id FROM core_requirement q JOIN institution_req i ON i.requirement_id=q.id JOIN communication_registry r ON r.comunicacion_id=q.communication_id WHERE CONCAT(r.folio_prefix,'-',LPAD(CONCAT('',r.numero),r.folio_width,'0'))=?",folio);});}
    private String scope(Operador a,String alias,boolean head){var terms=new ArrayList<String>();for(var x:a.accesos()){boolean role=head?x.jefe():Set.of("PROFESIONAL","ADMINISTRATIVO").contains(x.rol());if(!role||x.alcance().equals("MATERIA"))continue;if(x.area()!=null)terms.add("("+alias+".unit_code="+lit(x.unidad())+" AND "+alias+".site_id="+lit(x.sede())+" AND "+alias+".area_id="+lit(x.area())+" AND EXISTS(SELECT 1 FROM institution_area ia WHERE ia.id="+alias+".area_id AND ia.valid_from<="+clock.millis()+" AND ia.valid_until>"+clock.millis()+"))");else if(Set.of("INSTITUCION","SEDE","UNIDAD_SEDE").contains(x.alcance()))terms.add("("+alias+".area_id IS NULL"+(x.alcance().equals("INSTITUCION")?"":" AND "+alias+".site_id="+lit(x.sede())+(x.unidad()==null?"":" AND "+alias+".unit_code="+lit(x.unidad())))+")");}return "("+String.join(" OR ",terms.isEmpty()?List.of("1=0"):terms)+")";}
    /** Sustituye la unión de destinos históricos para los agregados U2, también en COUNT y búsquedas. */
    String alcanceCom(Operador a,String com){String root="EXISTS(SELECT 1 FROM institution_req i JOIN core_requirement q ON q.id=i.requirement_id WHERE q.communication_id="+com+" AND ("+scope(a,"i",true)+" OR (i.attention_actor="+lit(a.id())+" AND "+scope(a,"i",false)+")))";String pending="EXISTS(SELECT 1 FROM institution_sol s JOIN core_destination d ON d.id=s.destination_id LEFT JOIN destination_area da ON da.destination_id=d.id WHERE s.communication_id="+com+" AND s.state='PENDIENTE' AND "+scope(a,"v",true).replace("v.unit_code","d.unit_code").replace("v.site_id","d.site_id").replace("v.area_id","da.area_id")+")";String manual="EXISTS(SELECT 1 FROM core_manual m WHERE m.communication_id="+com+" AND m.actor_id="+lit(a.id())+")";return "("+root+" OR "+pending+" OR "+manual+")";}
    static String administrado(String com){return "(EXISTS(SELECT 1 FROM institution_sol z WHERE z.communication_id="+com+") OR EXISTS(SELECT 1 FROM institution_req iz JOIN core_requirement qz ON qz.id=iz.requirement_id WHERE qz.communication_id="+com+"))";}
    public List<Map<String,Object>> solicitudes(Operador a){return db.transaction(()->{guard(a);return db.sql.queryForList("SELECT sx.id FROM institution_sol sx WHERE "+alcanceCom(a,"sx.communication_id")+" ORDER BY sx.created_ms DESC LIMIT 100").stream().map(r->solicitud(a,uuid(r.get("id")))).toList();});}
    public Map<String,Object> solicitud(Operador a,UUID id){return db.transaction(()->{guard(a);var r=sol(id);core.autorizarLectura(a,uuid(r.get("communication_id")));var out=normal(r);boolean h=vigente(r)&&a.jefeEn(s(r,"unit_code"),s(r,"site_id"),s(r,"area_id"));out.put("puedeDecidir",h&&"PENDIENTE".equals(r.get("state")));out.put("historial",h?normalList("SELECT revision,actor_id,at_ms,action_code,reason_text,snapshot_doc FROM institution_flow_history WHERE resource_id=? ORDER BY seq",id(id)):List.of());return out;});}
    public List<Map<String,Object>> requerimientos(Operador a){return db.transaction(()->{guard(a);return db.sql.queryForList("SELECT i.requirement_id FROM institution_req i JOIN core_requirement q ON q.id=i.requirement_id WHERE "+scope(a,"i",true)+" OR (i.attention_actor="+lit(a.id())+" AND "+scope(a,"i",false)+") ORDER BY q.created_ms DESC LIMIT 100").stream().map(r->requerimiento(a,uuid(r.get("requirement_id")))).toList();});}
    public Map<String,Object> requerimiento(Operador a,UUID id){return db.transaction(()->{guard(a);var r=req(id);lector(a,r);var out=normal(r);out.put("jefaturasVigentes",cat.operadores().stream().filter(h->h.jefeEn(s(r,"unit_code"),s(r,"site_id"),s(r,"area_id"))).map(Operador::id).toList());out.put("jefatura",a.jefeEn(s(r,"unit_code"),s(r,"site_id"),s(r,"area_id")));var cases=normalList("SELECT c.id,c.state,d.unit_code,d.site_id FROM core_case c JOIN core_destination d ON d.id=c.destination_id WHERE c.requirement_id=? ORDER BY c.created_ms,c.id",id(id));out.put("sinCasos",cases.isEmpty());out.put("casos",Boolean.TRUE.equals(out.get("jefatura"))?cases:cases.stream().filter(c->gestionaCaso(a,c)).toList());out.put("colaboraciones",Boolean.TRUE.equals(out.get("jefatura"))?normalList("SELECT id,unit_code,site_id,area_id,state,revision,case_id FROM institution_collaboration WHERE requirement_id=? ORDER BY created_ms,id",id(id)):List.of());out.put("historial",normalList("SELECT revision,actor_id,at_ms,action_code,reason_text,snapshot_doc FROM institution_flow_history WHERE resource_id=? ORDER BY seq",id(id)));return out;});}
    public List<Map<String,Object>> colaboraciones(Operador a){return db.transaction(()->{guard(a);return normalList("SELECT p.id,p.requirement_id,p.unit_code,p.site_id,p.area_id,p.objective_text,p.state,p.revision FROM institution_collaboration p WHERE "+scope(a,"p",true)+" ORDER BY p.created_ms DESC LIMIT 100");});}
}
